#include <iostream>
#include <string>
#include <vector>
#include <cstdlib>

int main() {
    std::vector<std::string> hi = {"h", "e", "l", "l", "o"};
    std::string s;
    int counter = 0;
    int length = hi.size();

    if (!(std::cin >> s)) {
        std::cerr << "Error reading input" << std::endl;
        std::exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < s.size(); ++i) {
        if (std::string(1, s[i]) == hi[counter]) {
            counter++;
            if (counter == length) {
                std::cout << "YES" << std::endl;
                return 0;
            }
        }
    }
    std::cout << "NO" << std::endl;
    return 0;
}

